use crate::{openrouter::OpenRouter,store::{text,uid,now,Result}};
use serde_json::{json,Value};

fn request_url(value:&str,base:&str)->Result<String>{let u=reqwest::Url::parse(value).map_err(|_|"Higgsfield returned an invalid request URL.")?;let b=reqwest::Url::parse(base).map_err(|_|"Invalid Higgsfield endpoint.")?;if u.origin()!=b.origin()||!u.username().is_empty()||u.password().is_some(){return Err("Higgsfield returned an unexpected request URL.".into());}Ok(u.into())}
fn media_url(value:&str,base:&str)->Result<String>{let u=reqwest::Url::parse(value).map_err(|_|"The provider returned an invalid media URL.")?;let b=reqwest::Url::parse(base).map_err(|_|"Invalid Higgsfield endpoint.")?;let local=["localhost","127.0.0.1","[::1]","::1"].contains(&b.host_str().unwrap_or(""));let host=u.host_str().unwrap_or("");let private=host=="localhost"||host.ends_with(".local")||host.starts_with("[::")||host.parse::<std::net::Ipv4Addr>().is_ok_and(|ip|ip.is_private()||ip.is_loopback()||ip.is_link_local()||ip.is_unspecified());if !["https","http"].contains(&u.scheme())||!u.username().is_empty()||u.password().is_some()||!local&&(u.scheme()!="https"||private){return Err("The provider returned an unsafe media URL.".into());}Ok(u.into())}
async fn checked(r:std::result::Result<reqwest::Response,reqwest::Error>)->Result<reqwest::Response>{let r=r.map_err(|_|"Higgsfield request interrupted. Check your connection and provider activity.")?;if !r.status().is_success(){return Err(format!("Higgsfield returned HTTP {}. Check your key, credits, and model access.",r.status().as_u16()));}Ok(r)}
impl OpenRouter{
 fn hf_context(&self,j:&Value,require_enabled:bool)->Result<(Value,Value,String)>{let s=self.store.read();let p=s["settings"]["providers"].as_array().and_then(|a|a.iter().find(|p|p["id"]==j["provider"]&&p["type"]=="higgsfield")).cloned().ok_or("Choose a connected Higgsfield model in Settings → Video.")?;let catalog=crate::providers::video_catalog();let m=catalog.as_array().unwrap().iter().find(|m|m["id"]==j["engine"]&&(!require_enabled||p["models"].as_array().is_some_and(|a|a.iter().any(|e|e["id"]==m["id"]&&e["kind"]=="video")))).cloned().ok_or("Choose a supported Higgsfield video model.")?;let key=self.secrets.lock().unwrap()["providerKeys"][text(&p,"id")].as_str().unwrap_or("").to_string();if key.is_empty(){return Err("Add your Higgsfield API key in Settings → Video.".into());}Ok((p,m,key))}
 pub fn video_claim(&self,id:&str)->Result<()>{let s=self.store.read();let j=s["jobs"].as_array().unwrap().iter().find(|j|j["id"]==id).ok_or("Take not found.")?;if !crate::providers::is_api(&text(j,"provider")){return self.claim(id);}self.hf_context(j,true)?;self.store.update(|s|{let j=s["jobs"].as_array_mut().unwrap().iter_mut().find(|j|j["id"]==id).ok_or("Take not found.")?;if j["kind"]!="video"||j["status"]!="prepared"{return Err("This video has already been submitted.".into());}j["status"]=json!("submitting");j["error"]=json!("");Ok(())})}
 pub(crate) async fn higgsfield_request(&self,j:&Value,submit:bool)->Result<()>{let(p,m,key)=self.hf_context(j,false)?;let base=text(&p,"baseUrl");let auth=format!("Key {key}");let id=text(j,"id");
  if submit{if j["status"]!="submitting"||!text(j,"videoRemoteId").is_empty(){return Ok(());}let image=!text(&j["inputs"],"avatar").is_empty();let mut body=m["requestDefaults"].clone();body["prompt"]=if j["prompt"].is_string(){j["prompt"].clone()}else{j["text"].clone()};for field in["duration","resolution","aspect_ratio"]{if !j["video"][field].is_null()&&!(image&&field=="aspect_ratio"){body[field]=j["video"][field].clone();}}
   if image{let asset=self.store.asset(&text(&j["inputs"],"avatar"))?;let bytes=tokio::fs::read(self.store.asset_path(&asset)?).await.map_err(|_|"The reference photo is missing.")?;if bytes.len()>20*1024*1024{return Err("Use a photo smaller than 20 MB.".into());}let ticket:Value=checked(self.client.post(format!("{base}/files/generate-upload-url")).header("Authorization",&auth).json(&json!({"content_type":asset["type"]})).send().await).await?.json().await.map_err(|_|"Higgsfield returned an invalid upload response.")?;let mut upload=self.client.put(media_url(&text(&ticket,"upload_url"),&base)?).body(bytes);if let Some(headers)=ticket["upload_headers"].as_object(){for(name,value)in headers{if !["authorization","cookie","x-api-key","xi-api-key"].contains(&name.to_lowercase().as_str()){upload=upload.header(name,value.as_str().unwrap_or(""));}}}checked(upload.send().await).await?;body["image_url"]=json!(media_url(&text(&ticket,"public_url"),&base)?);}
   self.store.patch_job(&id,json!({"submissionAttempted":true,"stage":"Submitting to Higgsfield"}))?;let path=if image{text(&m,"imagePath")}else{text(&m,"id")};let result:Value=checked(self.client.post(format!("{base}/{path}")).header("Authorization",&auth).header("Idempotency-Key",&id).json(&body).send().await).await?.json().await.map_err(|_|"Higgsfield returned an invalid submission response.")?;let remote=text(&result,"request_id");if remote.is_empty(){return Err("No request ID returned. Check Higgsfield activity before creating another take.".into());}let status=request_url(&text(&result,"status_url"),&base)?;let cancel=if text(&result,"cancel_url").is_empty(){String::new()}else{request_url(&text(&result,"cancel_url"),&base)?};return self.store.patch_job(&id,json!({"videoRemoteId":remote,"higgsfieldStatusUrl":status,"higgsfieldCancelUrl":cancel,"status":"queued","stage":"Queued at Higgsfield"}));
  }
  if text(j,"videoRemoteId").is_empty()||!["queued","running","cancel_requested"].contains(&text(j,"status").as_str()){return Ok(());}
  let result:Value=checked(self.client.get(request_url(&text(j,"higgsfieldStatusUrl"),&base)?).header("Authorization",&auth).send().await).await?.json().await.map_err(|_|"Higgsfield returned an invalid video status.")?;
  match text(&result,"status").as_str(){"queued"|"in_progress"=>return self.store.patch_job(&id,json!({"status":if result["status"]=="queued"{"queued"}else{"running"},"stage":"Generating video at Higgsfield","error":""})),"failed"|"nsfw"|"canceled"=>return self.store.patch_job(&id,json!({"status":if result["status"]=="canceled"{"cancelled"}else{"failed"},"error":if result["status"]=="nsfw"{"Higgsfield rejected this request under its content policy."}else if result["status"]=="failed"{"Higgsfield could not generate this video. Check the request in your provider account."}else{""}})),"completed"=>{},_=>return Err("Higgsfield returned an unknown video status.".into())}
  let mut r=checked(self.client.get(media_url(&text(&result["video"],"url"),&base)?).send().await).await?;let mut bytes=vec![];while let Some(chunk)=r.chunk().await.map_err(|_|"Video download interrupted.")?{if bytes.len()+chunk.len()>512*1024*1024{return Err("Video exceeds 512 MB.".into());}bytes.extend_from_slice(&chunk);}let mp4=bytes.len()>=12&&&bytes[4..8]==b"ftyp";let webm=bytes.starts_with(&[0x1a,0x45,0xdf,0xa3]);if !mp4&&!webm{return Err("Higgsfield returned an unsupported video file.".into());}let ext=if mp4{"mp4"}else{"webm"};let aid=uid();tokio::fs::write(self.store.dir.join("media").join(&aid),&bytes).await.map_err(|_|"Could not save video.")?;self.store.update(|s|{s["assets"].as_array_mut().unwrap().push(json!({"id":aid,"name":format!("{}.{ext}",text(j,"sectionTitle")),"type":format!("video/{ext}"),"size":bytes.len(),"createdAt":now()}));let j=s["jobs"].as_array_mut().unwrap().iter_mut().find(|j|j["id"]==id).ok_or("Take not found.")?;j["status"]=json!("completed");j["outputId"]=json!(aid);j["error"]=json!("");j["updatedAt"]=json!(now());Ok(())})
 }
 pub async fn higgsfield_cancel(&self,id:&str)->Result<()>{let s=self.store.read();let j=s["jobs"].as_array().unwrap().iter().find(|j|j["id"]==id).ok_or("Take not found.")?;if j["status"]=="prepared"{return self.store.patch_job(id,json!({"status":"cancelled"}));}if j["sequence"].is_object()||text(j,"videoRemoteId").is_empty()||j["status"]!="queued"{return Err("Only a queued Higgsfield video can be cancelled.".into());}let(p,_,key)=self.hf_context(j,false)?;checked(self.client.post(request_url(&text(j,"higgsfieldCancelUrl"),&text(&p,"baseUrl"))?).header("Authorization",format!("Key {key}")).send().await).await?;self.store.patch_job(id,json!({"status":"cancel_requested","stage":"Cancellation requested at Higgsfield"}))?;self.video_run(id.into(),false).await;Ok(())}
}
#[cfg(test)]
mod tests{
 use super::*;use crate::store::Store;use std::sync::{Arc,Mutex};use tokio::{net::TcpListener,io::{AsyncReadExt,AsyncWriteExt}};
 async fn serve(listener:TcpListener,replies:Vec<(String,String,Vec<u8>)>)->Vec<String>{let mut requests=vec![];for(path,mime,body)in replies{let(mut socket,_)=tokio::time::timeout(std::time::Duration::from_secs(5),listener.accept()).await.unwrap().unwrap();let mut bytes=vec![];loop{let mut buf=[0u8;4096];let n=socket.read(&mut buf).await.unwrap();assert!(n>0);bytes.extend_from_slice(&buf[..n]);if let Some(end)=bytes.windows(4).position(|w|w==b"\r\n\r\n"){let header=String::from_utf8_lossy(&bytes[..end]).to_lowercase();let len=header.lines().find_map(|line|line.strip_prefix("content-length: ").and_then(|v|v.parse::<usize>().ok())).unwrap_or(0);if bytes.len()>=end+4+len{break;}}}let request=String::from_utf8_lossy(&bytes).to_string();assert!(request.lines().next().unwrap().contains(&path),"{request}");requests.push(request);socket.write_all(format!("HTTP/1.1 200 OK\r\nContent-Type: {mime}\r\nContent-Length: {}\r\nConnection: close\r\n\r\n",body.len()).as_bytes()).await.unwrap();socket.write_all(&body).await.unwrap();}requests}
 fn client(dir:&std::path::Path,base:&str,image:bool)->OpenRouter{let store=Store::open(dir.into()).unwrap();store.update(|s|{s["settings"]["providers"]=json!([{"id":"api:hf","type":"higgsfield","baseUrl":base,"models":[crate::providers::video_catalog()[0]]}]);s["jobs"]=json!([{"id":"job","kind":"video","provider":"api:hf","engine":crate::providers::video_catalog()[0]["id"],"status":"prepared","text":"A sunrise","sectionTitle":"Clip","video":{"duration":5,"resolution":"720p","aspect_ratio":"16:9"},"inputs":if image{json!({"avatar":"photo"})}else{json!({})}}]);if image{s["assets"]=json!([{"id":"photo","type":"image/png"}]);}Ok(())}).unwrap();OpenRouter::new(store,Arc::new(Mutex::new(json!({"providerKeys":{"api:hf":"dummy-hf-key"}}))))}
 fn reply(path:&str,v:Value)->(String,String,Vec<u8>){(path.into(),"application/json".into(),v.to_string().into_bytes())}
 #[tokio::test]async fn native_video_uses_higgsfield_key_and_resumes_without_duplicate_submission(){let listener=TcpListener::bind("127.0.0.1:0").await.unwrap();let base=format!("http://{}",listener.local_addr().unwrap());let mp4=b"\x00\x00\x00\x14ftypisom\x00\x00\x00\x00".to_vec();let server=tokio::spawn(serve(listener,vec![reply("/bytedance/seedance-2.5/text-to-video",json!({"request_id":"remote","status_url":format!("{base}/requests/remote/status"),"cancel_url":format!("{base}/requests/remote/cancel")})),reply("/requests/remote/status",json!({"status":"in_progress"})),reply("/requests/remote/status",json!({"status":"completed","video":{"url":format!("{base}/video.mp4")}})),("/video.mp4".into(),"video/mp4".into(),mp4)]));let dir=tempfile::tempdir().unwrap();let c=client(dir.path(),&base,false);c.video_claim("job").unwrap();assert!(c.video_claim("job").is_err());c.video_run("job".into(),true).await;assert_eq!(c.store.read()["jobs"][0]["status"],"queued");c.store.update(|s|{s["settings"]["providers"][0]["models"]=json!([]);Ok(())}).unwrap();c.video_run("job".into(),false).await;assert_eq!(c.store.read()["jobs"][0]["status"],"running");c.video_run("job".into(),false).await;assert_eq!(c.store.read()["jobs"][0]["status"],"completed");c.video_run("job".into(),false).await;let requests=server.await.unwrap();assert!(requests[0].contains("authorization: Key dummy-hf-key"));assert!(requests[0].contains("idempotency-key: job"));assert!(!requests[3].to_lowercase().contains("authorization:"));}
 #[tokio::test]async fn native_image_upload_uses_storage_headers_without_api_auth(){let listener=TcpListener::bind("127.0.0.1:0").await.unwrap();let base=format!("http://{}",listener.local_addr().unwrap());let server=tokio::spawn(serve(listener,vec![reply("/files/generate-upload-url",json!({"upload_url":format!("{base}/upload?signature=temporary"),"public_url":format!("{base}/photo.png"),"upload_headers":{"Content-Type":"image/png","x-amz-tagging":"retention=temporary"}})),("/upload?signature=temporary".into(),"text/plain".into(),vec![]),reply("/bytedance/seedance-2.5/image-to-video",json!({"request_id":"image","status_url":format!("{base}/requests/image/status")}))]));let dir=tempfile::tempdir().unwrap();let c=client(dir.path(),&base,true);std::fs::write(dir.path().join("media/photo"),"photo").unwrap();c.video_claim("job").unwrap();c.video_run("job".into(),true).await;assert_eq!(c.store.read()["jobs"][0]["status"],"queued");let requests=server.await.unwrap();assert!(!requests[1].to_lowercase().contains("authorization:"));assert!(requests[1].contains("x-amz-tagging: retention=temporary"));assert!(requests[2].contains("image_url"));assert!(!requests[2].contains("aspect_ratio"));}
 #[test]fn rejects_auth_redirects_and_private_media(){assert!(request_url("https://other.example/steal","https://api.higgsfield.ai").is_err());for url in["file:///tmp/key","https://127.0.0.1/video","http://cdn.example/video","https://user:key@cdn.example/video"]{assert!(media_url(url,"https://api.higgsfield.ai").is_err());}}
}
